import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
CHECK = "checkout-preserves-total"


def run():
    from checkout import checkout

    try:
        total = checkout(1250)
    except TypeError as exc:
        if str(exc) != "'int' object is not subscriptable":
            raise
        return "reproduced", "checkout(1250) raises TypeError instead of returning 1250", 1
    if total != 1250:
        return "reproduced", f"checkout(1250) returned {total!r} instead of 1250", 1
    return "passed", "checkout(1250) returns 1250", 0


try:
    outcome, reason, code = run()
except Exception as exc:
    outcome, reason, code = "error", f"{type(exc).__name__}: {exc}", 2
print("NEIN_PROBE_RESULT " + json.dumps({"check": CHECK, "outcome": outcome, "reason": reason}))
sys.exit(code)

